ALTER TABLE "cenit"."purchase_requests" ADD COLUMN "extraction_id" uuid;--> statement-breakpoint
ALTER TABLE "cenit"."purchase_requests" ADD COLUMN "processor_version" text;--> statement-breakpoint
ALTER TABLE "cenit"."purchase_requests" ADD COLUMN "processed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "cenit"."purchase_requests" ADD CONSTRAINT "purchase_source" CHECK ((("cenit"."purchase_requests"."source" = 'manual' AND "cenit"."purchase_requests"."example_id" IS NULL) OR ("cenit"."purchase_requests"."source" = 'contract_example' AND "cenit"."purchase_requests"."example_id" IS NOT NULL AND "cenit"."purchase_requests"."example_id" IN ('recovered', 'partial', 'ambiguous'))) AND "cenit"."purchase_requests"."extraction_id" IS NULL AND "cenit"."purchase_requests"."processor_version" IS NULL AND "cenit"."purchase_requests"."processed_at" IS NULL OR ("cenit"."purchase_requests"."source" = 'image_capture' AND "cenit"."purchase_requests"."example_id" IS NULL AND "cenit"."purchase_requests"."extraction_id" IS NOT NULL AND "cenit"."purchase_requests"."processor_version" IS NOT NULL AND "cenit"."purchase_requests"."processor_version" ~ '^[a-zA-Z0-9._-]{1,100}$' AND "cenit"."purchase_requests"."processed_at" IS NOT NULL AND isfinite("cenit"."purchase_requests"."processed_at")));